        def execute_routing():
            routing_decision = {'task_type': task_type, 'provider_domain': selected_domain.value, 'routed_model': selected_model, 'gaming_coexistence_active': is_gaming, 'cost_adjusted': payload['estimated_cost'], 'status': 'OPTIMIZED_FEDERATED_ROUTE_DISPATCHED'}
            evidence_id = None
            if self.evidence_store is not None:
                try:
                    from core.cognition.evidence.envelope import EvidenceEnvelope
                    env = EvidenceEnvelope.create(task_id=f'TASK-ROUTE-{uuid.uuid4().hex[:8].upper()}', provider=selected_domain.value, model_name=selected_model, capability=task_type, input_prompt=task_description, output_payload=json.dumps(routing_decision, sort_keys=True), execution_duration_ms=1.5, policy_status='APPROVED', signing_key=getattr(self.decision_engine, 'hmac_key', None))
                    self.evidence_store.store_evidence(env)
                    evidence_id = env.evidence_id
                    routing_decision['evidence_id'] = evidence_id
                except Exception as ee:
                    logger.warning(f'[ROUTER] Evidence envelope error: {ee}')
            if self.decision_engine is not None:
                try:
                    self.decision_engine.record_decision(subsystem='CognitiveRouter', decision_type='FEDERATED_MODEL_ROUTING', context={'gaming_active': is_gaming, 'task_type': task_type, 'estimated_tokens': estimated_tokens, 'evidence_id': evidence_id}, action_payload=routing_decision, rationale=f'Routed {task_type} to {selected_domain.value} ({selected_model}) with Evidence {evidence_id}.')
