def classify_record(source_path: str, content: str, current_memory_type: str) -> str:
    path_lower = source_path.lower()
    content_lower = content.lower()
    if 'registry/core' in path_lower or 'registry/personality' in path_lower or 'constitution' in path_lower or (current_memory_type == 'identity_core'):
        return 'IDENTITY'
    rpg_markers = ['rpg', 'wow', 'wotlk', 'druid', 'capcap', 'identity forge', 'lore', 'intentions', 'persona']
    if any((m in path_lower or m in content_lower for m in rpg_markers)):
        return 'RPG_MEMORY'
    if 'ledger' in path_lower or 'decision' in path_lower or current_memory_type == 'experience_ledger':
        return 'EXPERIENCE'
    if 'security' in path_lower or 'audit' in path_lower or current_memory_type == 'security_audit':
        return 'SECURITY'
    if 'bridge' in path_lower or 'state' in path_lower or 'telemetry' in path_lower or ('config' in path_lower):
        return 'OPERATIONAL'
    noise_markers = ['test', 'sandbox', 'fuzz', 'chaos', 'soak', 'benchmark', 'mock']
    if any((m in path_lower for m in noise_markers)):
        return 'SYNTHETIC_NOISE'
    return 'OPERATIONAL'

def classify_tier(*, latency_ms: float, context_window: int | None, supports_json: bool, supports_tools: bool, supports_reasoning: bool) -> str:
    if supports_reasoning and (context_window or 0) >= 64000:
        return 'HEAVY'
    if latency_ms <= 900.0 and supports_json:
        return 'FAST'
    if latency_ms <= 2500.0 or supports_tools:
        return 'MID'
    return 'HEAVY'

def classify(self, query: str) -> Dict[str, Any]:
    query_lower = query.lower()
    for pattern in self.MEMORY_TRIGGERS:
        if re.search(pattern, query_lower):
            return {'intent': IntentType.MEMORY_QUERY, 'confidence': 0.9, 'target_provider': 'evidence_store'}
    for pattern in self.SEARCH_TRIGGERS:
        if re.search(pattern, query_lower):
            return {'intent': IntentType.WEB_SEARCH, 'confidence': 0.85, 'target_provider': 'tavily'}
    for pattern in self.CODE_TRIGGERS:
        if re.search(pattern, query_lower):
            return {'intent': IntentType.CODE_EXECUTION, 'confidence': 0.88, 'target_provider': 'system_executor'}
    for pattern in self.VOICE_TRIGGERS:
        if re.search(pattern, query_lower):
            return {'intent': IntentType.VOICE_ACTION, 'confidence': 0.92, 'target_provider': 'voice_gateway'}
    for pattern in self.REASONING_TRIGGERS:
        if re.search(pattern, query_lower):
            return {'intent': IntentType.DEEP_REASONING, 'confidence': 0.8, 'target_provider': 'gemini'}
    for pattern in self.CREATIVE_TRIGGERS:
        if re.search(pattern, query_lower):
            return {'intent': IntentType.CREATIVE_SYNTHESIS, 'confidence': 0.85, 'target_provider': 'gemini'}
    return {'intent': IntentType.LOCAL_CHAT, 'confidence': 1.0, 'target_provider': 'ollama'}

def classify_segment(self, segment_id: str, text: str, hint_category: Optional[str]=None) -> ClassifiedContextSegment:
    """Classifies a context segment into its appropriate tier and strategy."""
    clean_text = text.strip()
    chars = len(clean_text)
    est_tokens = max(1, chars // 4)
    text_low = clean_text.lower()
    if 'sovereign rule' in text_low or 'immutable_rules' in text_low or 'constitution' in text_low or ('decision_ledger' in text_low) or ('ezzio sovereign context' in text_low) or (hint_category == 'CONSTITUTION'):
        return ClassifiedContextSegment(segment_id=segment_id, category=ContentCategory.CONSTITUTION, tier=ContextSensitivityTier.INVIOLABLE, raw_text=clean_text, raw_char_count=chars, estimated_raw_tokens=est_tokens)
    if clean_text.startswith('{') and clean_text.endswith('}') or (clean_text.startswith('[') and clean_text.endswith(']')) or hint_category == 'JSON_DATA':
        return ClassifiedContextSegment(segment_id=segment_id, category=ContentCategory.JSON_DATA, tier=ContextSensitivityTier.BULK_REDUNDANT, raw_text=clean_text, raw_char_count=chars, estimated_raw_tokens=est_tokens)
    if 'traceback' in text_low or 'stderr:' in text_low or 'stdout:' in text_low or (hint_category in {'LOGS', 'TOOL_OUTPUT'}):
        return ClassifiedContextSegment(segment_id=segment_id, category=ContentCategory.TOOL_OUTPUT, tier=ContextSensitivityTier.BULK_REDUNDANT, raw_text=clean_text, raw_char_count=chars, estimated_raw_tokens=est_tokens)
    if 'def ' in clean_text or 'class ' in clean_text or 'import ' in clean_text or (hint_category == 'CODE'):
        return ClassifiedContextSegment(segment_id=segment_id, category=ContentCategory.CODE, tier=ContextSensitivityTier.BULK_REDUNDANT, raw_text=clean_text, raw_char_count=chars, estimated_raw_tokens=est_tokens)
    return ClassifiedContextSegment(segment_id=segment_id, category=ContentCategory.PROSE, tier=ContextSensitivityTier.SEMANTIC, raw_text=clean_text, raw_char_count=chars, estimated_raw_tokens=est_tokens)

