def scan_and_classify(self) -> Dict[str, Any]:
    """Scanne les fichiers critiques et classifie les états d'intégrité."""
    baseline_data = json.loads(self.baseline_path.read_text(encoding='utf-8'))
    stored_hashes = baseline_data.get('files', {})
    critical_files = [self.root_dir / 'core' / 'constitution' / 'ezzio_genome.json', self.root_dir / 'core' / 'constitution' / 'ezzio_global_framework.py']
    report = {}
    for f in critical_files:
        if not f.exists():
            continue
        rel = f.relative_to(self.root_dir).as_posix()
        current_hash = hashlib.sha256(f.read_bytes()).hexdigest().lower()
        expected_hash = stored_hashes.get(rel)
        if expected_hash is None:
            classification = 'NEW_UNTRACKED_FILE'
        elif current_hash == expected_hash:
            classification = 'UNCHANGED'
        else:
            classification = 'UNKNOWN_DRIFT_DETECTED'
        report[rel] = {'status': classification, 'current_hash': current_hash[:16] + '...', 'expected_hash': expected_hash[:16] + '...' if expected_hash else 'N/A'}
    return {'timestamp_utc': datetime.now(timezone.utc).isoformat(), 'scan_mode': 'CLASSIFICATION_NON_BLOCKING', 'report': report}

def classify_action_risk(action_type: str, target: str) -> tuple[RiskLevel, bool]:
    if action_type.startswith('GET_') or action_type.startswith('SEARCH_') or action_type in ['INSPECT_EVIDENCE', 'TASK_CHAT', 'TASK_FAST_REPLY', 'TASK_GENERAL', 'TASK_REASONING', 'TASK_RESEARCH', 'TASK_FORENSIC', 'TASK_POWERSHELL', 'TASK_PYTHON', 'TASK_CODE', 'TASK_STRUCTURED_JSON']:
        return (RiskLevel.READ_ONLY, False)
    if action_type in ['REQUEST_TASK_RESUME', 'PING_SERVICE']:
        return (RiskLevel.LOW, False)
    if action_type in ['REQUEST_TASK_EXECUTION', 'RUN_HEALTH_CHECK']:
        return (RiskLevel.MEDIUM, False)
    if action_type in ['REQUEST_TASK_CANCEL', 'RESTART_SUBCOMPONENT', 'TRIGGER_BACKUP_ROTATION']:
        return (RiskLevel.HIGH, True)
    if action_type in ['PURGE_CACHE', 'EMERGENCY_SHUTDOWN', 'RESET_SESSION', 'TASK_CRITICAL_OPERATION']:
        return (RiskLevel.CRITICAL, True)
    return (RiskLevel.HIGH, True)

def classify_user_prompt(prompt: str) -> Tuple[str, str, float]:
    p_lower = prompt.lower()
    for task_type, keywords in TASK_PRIORITY_ORDER:
        if any((k in p_lower for k in keywords)):
            complexity = 'HIGH' if task_type in ['FORENSIC', 'CODE', 'POWERSHELL', 'PYTHON', 'CRITICAL_OPERATION'] else 'LOW'
            return (task_type, complexity, 0.95)
    return ('GENERAL', 'MEDIUM', 0.7)
